func (p *DirectPeer) WaitAVDrain(timeout time.Duration) {
	if p.encodeCh == nil {
		return
	}
	fence := make(chan struct{})
	select {
	case p.encodeCh <- &mediapeer.RawAVSegment{Fence: fence}:
	case <-p.avPipelineCtx.Done():
		return
	case <-time.After(timeout):
		return
	}
	select {
	case <-fence:
	case <-p.avPipelineCtx.Done():
	case <-time.After(timeout):
	}
}

