	defer p.avPipelineWg.Done()

	for seg := range p.publishCh {
		if p.avPipelineCtx.Err() != nil {
			return
		}
		// Fence marker
		if seg.Fence != nil && len(seg.VP8Samples) == 0 {
			close(seg.Fence)
			continue
		}
		if p.isAVSegmentStale(seg) {
			continue
		}
		p.publishAVSegment(seg)
	}
}

