func silentAvatarMaxLead(info *pb.AvatarInfo) time.Duration {
	chunkDuration := silentAvatarDefaultMaxLead
	if info != nil {
		if d := time.Duration(float64(info.GetChunkDurationS()) * float64(time.Second)); d > 0 {
			chunkDuration = d
		}
		frames := int(info.GetFramesPerChunk())
		fps := int(info.GetOutputFps())
		if frames > 0 && fps > 0 {
			frameDuration := time.Duration(math.Round(float64(frames) * float64(time.Second) / float64(fps)))
			if frameDuration > chunkDuration {
				chunkDuration = frameDuration
			}
		}
	}
	if chunkDuration > silentAvatarMaxLeadCap {
		return silentAvatarMaxLeadCap
	}
	return chunkDuration
}

func (p *DirectPeer) prepareRawAVSegment(seg *mediapeer.RawAVSegment) bool {
	if seg == nil || p.isPlaybackStale(seg.Epoch) {
		return false
	}
	if seg.Supersedable {
		seg.SpeechEpochAtQueue = p.latestSpeechEpoch.Load()
	}
	if seg.Epoch > 0 {
		p.advanceLatestSpeechEpoch(seg.Epoch)
	}
	return !p.isRawAVSegmentStale(seg)
}

func (p *DirectPeer) advanceLatestSpeechEpoch(epoch uint64) {
	if epoch == 0 {
		return
	}
	for {
		current := p.latestSpeechEpoch.Load()
		if epoch <= current {
			return
		}
		if p.latestSpeechEpoch.CompareAndSwap(current, epoch) {
			return
		}
	}
}

func (p *DirectPeer) isRawAVSegmentStale(seg *mediapeer.RawAVSegment) bool {
	if seg == nil {
		return true
	}
	if p.isPlaybackStale(seg.Epoch) {
		return true
	}
	return seg.Supersedable && p.latestSpeechEpoch.Load() > seg.SpeechEpochAtQueue
}

func (b *Bot) isPlaybackStale(epoch uint64) bool {
	if epoch == 0 {
		return false
	}
	current := b.playbackEpoch.Load()
	return current > 0 && epoch < current
}

func (b *Bot) isRawAVSegmentStale(seg *RawAVSegment) bool {
	if seg == nil {
		return true
	}
	if b.isPlaybackStale(seg.Epoch) {
		return true
	}
	return seg.Supersedable && b.latestSpeechEpoch.Load() > seg.SpeechEpochAtQueue
}

